class TTLCache:
    """Fixed-capacity cache with per-entry TTL and LRU eviction."""

    def __init__(self, capacity: int, ttl: float):
        self.capacity = capacity
        self.ttl = ttl
        # key -> [value, written_at]; dict insertion order is the LRU order
        self._entries = {}

    def put(self, key, value, now: float) -> None:
        if self.capacity <= 0:
            return
        # Rule 5: drop every expired entry before any eviction happens.
        self._purge_expired(now)
        if key in self._entries:
            # Rule 4: update value, reset expiry clock, mark most recent.
            del self._entries[key]
        elif len(self._entries) >= self.capacity:
            # Still at capacity: evict the least recently used live entry.
            lru_key = next(iter(self._entries))
            del self._entries[lru_key]
        self._entries[key] = [value, now]

    def get(self, key, now: float):
        if key not in self._entries:
            return None
        value, written_at = self._entries[key]
        if (now - written_at) >= self.ttl:
            # Rule 1 + 2: expired at exactly ttl; return None and remove it.
            del self._entries[key]
            return None
        # Rule 3: counts as a use for recency, but keeps the original clock.
        del self._entries[key]
        self._entries[key] = [value, written_at]
        return value

    def _purge_expired(self, now: float) -> None:
        for key in [k for k in self._entries if (now - self._entries[k][1]) >= self.ttl]:
            del self._entries[key]
