class TTLCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}   # key -> (value, write_time)
        self._order = {}  # key -> None; dict order = LRU order (oldest first)

    def _touch(self, key):
        del self._order[key]
        self._order[key] = None

    def _expire(self, key):
        del self._data[key]
        del self._order[key]

    def put(self, key, value, now):
        if self.capacity <= 0:
            return
        if key in self._data:
            self._data[key] = (value, now)
            self._touch(key)
            return
        if len(self._data) >= self.capacity:
            expired = [k for k, (_v, t) in self._data.items() if now - t >= self.ttl]
            for k in expired:
                self._expire(k)
            if len(self._data) >= self.capacity:
                lru_key = next(iter(self._order))
                self._expire(lru_key)
        self._data[key] = (value, now)
        self._order[key] = None

    def get(self, key, now):
        if key not in self._data:
            return None
        value, t = self._data[key]
        if now - t >= self.ttl:
            self._expire(key)
            return None
        self._touch(key)
        return value
